def selected_identity():
    from fractions import Fraction
    cases=0
    for size in range(1,9):
        probs=[]
        for k in range(1,size+1):probs=[p*Fraction(k-1,k) for p in probs]+[Fraction(1,k)]
        assert probs==[Fraction(1,size)]*size
        for mask in range(1<<size):
            assert sum((q for i,q in enumerate(probs) if mask>>i&1),Fraction())==Fraction(mask.bit_count(),size);cases+=1
    return cases
